const iconPaths={play:'<path d="m8 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',next:'<path d="m5 5 10 7-10 7ZM19 5v14"/>',previous:'<path d="m19 5-10 7 10 7ZM5 5v14"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',link:'<path d="m9 15 6-6m-5 9-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m0 4a4 4 0 0 0 6 0l4-4a4 4 0 0 0-6-6l-2 2"/>',headphones:'<path d="M4 13V11a8 8 0 0 1 16 0v2"/><rect x="2" y="12" width="5" height="9" rx="2"/><rect x="17" y="12" width="5" height="9" rx="2"/>',heart:'<path d="M12 21 3 12C-2 5 7 0 12 7c5-7 14-2 9 5Z"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',volume:'<path d="M3 9h4l5-5v16l-5-5H3Zm13-2a7 7 0 0 1 0 10m3-13a11 11 0 0 1 0 16"/>',check:'<path d="m5 12 5 5L20 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',ticket:'<path d="M3 4h18v5a3 3 0 0 0 0 6v5H3v-5a3 3 0 0 0 0-6Z"/><path d="M15 6v2m0 3v2m0 3v2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',sound:'<path d="M4 10v4M8 6v12M12 3v18M16 7v10M20 10v4"/>'};
function icon(n){return `<svg class="svg-icon" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[n]||iconPaths.sound}</svg>`;}
function head(n,title,intro,tag='Propuesta de sistema · v0.1'){return `<section class="page-heading"><span class="tag">${tag}</span><span class="eyebrow">${n} / NOODO DESIGN SYSTEM</span><h1>${title}</h1><p>${intro}</p></section>`;}
function label(title,side='Reglas y muestras'){return `<div class="section-label"><h2>${title}</h2><span>${side}</span></div>`;}
function spec(title,demo,description,meta='PROPUESTA UI',contract=''){return `<article class="spec"><div class="spec-demo column">${demo}</div><div class="spec-info"><span class="meta">${meta}</span><h3>${title}</h3><p>${description}</p>${contract?`<details class="contract"><summary>Reglas, estados y comportamiento</summary><p>${contract}</p></details>`:''}</div></article>`;}
